practice.solution:
class Account {
  private owner: string;
  balance: number;

  constructor(owner: string, balance: number) {
    this.owner = owner;
    this.balance = balance;
  }

  deposit(amount: number) {
    this.balance += amount;
  }

  summary(): string {
    return `${this.owner}: ${this.balance}`;
  }
}

const account = new Account("Ana", 100);
account.deposit(20);
console.log(account.summary());
